<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_fallback_menu() { echo '<ul class="menu"><li><a href="' . esc_url( home_url( '/' ) ) . '">' . esc_html__( 'Home', 'social-discovery' ) . '</a></li><li><a href="' . esc_url( sd_home_url( 'discover' ) ) . '">' . esc_html__( 'Discover', 'social-discovery' ) . '</a></li><li><a href="' . esc_url( sd_home_url( 'communities' ) ) . '">' . esc_html__( 'Communities', 'social-discovery' ) . '</a></li>'; if ( is_user_logged_in() ) { echo '<li><a href="' . esc_url( sd_home_url( 'messages' ) ) . '">' . esc_html__( 'Messages', 'social-discovery' ) . '</a></li>'; } echo '<li><a href="' . esc_url( sd_home_url( 'about' ) ) . '">' . esc_html__( 'About', 'social-discovery' ) . '</a></li></ul>'; }
function sd_menu( $location, $class = '' ) { wp_nav_menu( array( 'theme_location' => $location, 'container' => false, 'menu_class' => trim( 'menu ' . $class ), 'fallback_cb' => 'sd_fallback_menu', 'depth' => 0 ) ); }
function sd_body_classes( $classes ) { $classes[] = 'sd-theme'; $classes[] = 'sd-header-' . sanitize_html_class( sd_get_option( 'sd_header_layout' ) ); if ( is_page_template( 'page-templates/blank-canvas.php' ) ) { $classes[] = 'sd-blank-canvas'; } return $classes; }
add_filter( 'body_class', 'sd_body_classes' );
